-- Fresh database baseline for CUT Human Resource Management and Employee Retention System.
create extension if not exists pgcrypto;

create table departments (id uuid primary key default gen_random_uuid(), name text not null unique, code text unique, created_at timestamptz not null default now());
create table profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role text not null default 'employee' check(role in ('administrator','hr','hr_manager','employee')), department_id uuid references departments(id), active boolean not null default true, created_at timestamptz not null default now());
create table employees (id uuid primary key default gen_random_uuid(), user_id uuid unique references auth.users(id), employee_number text not null unique, full_name text not null, email text unique, department_id uuid references departments(id), job_title text, grade text, staff_category text not null check(staff_category in ('academic','non_academic')), employment_type text not null default 'permanent', employment_status text not null default 'active' check(employment_status in ('active','on_leave','exited')), appointment_date date, contract_end_date date, probation_end_date date, exit_date date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table employee_requests (id uuid primary key default gen_random_uuid(), employee_id uuid not null references employees(id), request_type text not null, details text not null, status text not null default 'submitted' check(status in ('submitted','in_progress','resolved','cancelled')), assigned_to uuid references auth.users(id), resolution text, created_at timestamptz not null default now(), resolved_at timestamptz);
create table employment_contracts (id uuid primary key default gen_random_uuid(), employee_id uuid not null references employees(id), effective_on date not null, ends_on date, employment_type text not null, status text not null default 'active' check(status in ('active','expired','renewed','cancelled')), notes text, created_at timestamptz not null default now());
create table onboarding_tasks (id uuid primary key default gen_random_uuid(), employee_id uuid not null references employees(id), title text not null, due_on date, completed_at timestamptz, completed_by uuid references auth.users(id));
create table leave_balances (id uuid primary key default gen_random_uuid(), employee_id uuid not null references employees(id), leave_year integer not null, leave_type text not null, entitled_days numeric(5,1) not null, carried_over_days numeric(5,1) not null default 0, unique(employee_id,leave_year,leave_type));
create table leave_requests (id uuid primary key default gen_random_uuid(), employee_id uuid not null references employees(id), leave_type text not null, starts_on date not null, ends_on date not null check(ends_on >= starts_on), requested_days numeric(5,1) not null check(requested_days > 0), reason text, status text not null default 'pending' check(status in ('pending','approved','rejected','cancelled')), reviewed_by uuid references auth.users(id), review_notes text, created_at timestamptz not null default now());
create table hr_cases (id uuid primary key default gen_random_uuid(), employee_id uuid references employees(id), case_type text not null, confidential boolean not null default true, status text not null default 'open' check(status in ('open','in_progress','closed')), owner_id uuid references auth.users(id), due_on date, summary text not null, outcome text, created_at timestamptz not null default now(), closed_at timestamptz);
create table engagement_surveys (id uuid primary key default gen_random_uuid(), title text not null, opens_on date not null, closes_on date not null, status text not null default 'draft' check(status in ('draft','open','closed')), created_by uuid references auth.users(id));
create table survey_responses (id uuid primary key default gen_random_uuid(), survey_id uuid not null references engagement_surveys(id) on delete cascade, employee_id uuid references employees(id), answers jsonb not null default '{}'::jsonb, submitted_at timestamptz not null default now(), unique(survey_id,employee_id));
create table retention_actions (id uuid primary key default gen_random_uuid(), title text not null, concern text not null, owner_id uuid references auth.users(id), due_on date, status text not null default 'open' check(status in ('open','in_progress','completed','cancelled')), outcome text, created_at timestamptz not null default now());
create table exit_cases (id uuid primary key default gen_random_uuid(), employee_id uuid not null references employees(id), exit_type text not null check(exit_type in ('resignation','retirement','contract_end','termination','death_in_service','transfer','other')), classification text not null check(classification in ('voluntary','involuntary','administrative')), reason text, notice_date date, last_day date, status text not null default 'open' check(status in ('open','under_review','completed','cancelled')), interview_notes text, created_by uuid references auth.users(id), completed_by uuid references auth.users(id), completed_at timestamptz, created_at timestamptz not null default now());
create table exit_checklist_items (id uuid primary key default gen_random_uuid(), exit_case_id uuid not null references exit_cases(id) on delete cascade, label text not null, required boolean not null default true, completed_at timestamptz, completed_by uuid references auth.users(id), notes text);
create table notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), title text not null, message text not null, read_at timestamptz, created_at timestamptz not null default now());
create table audit_events (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
